// One opt-in audio context, no timers; short-lived voices disconnect on completion.
// With the sound store (tools/sound-engineer) it plays a looping bed for the hour and weather and, now and then,
// the rooster at dawn, birds by day, an owl at night, thunder in storms and the animals on the ranch.
// Without it (no catalogue or no audio yet) it keeps the original synthesised chirp.
const SOURCES=['/api/sounds','/sounds/manifest.json'];
const MASTER=.55,BED=.5,SHOT=.7;
function bedFor(h,weather){if(weather==='hail')return 'rain-heavy';if(weather==='rain')return 'rain-light';if(weather==='snow')return 'snowy';if(weather==='wind')return 'wind-gentle';if(h>=5&&h<7)return 'farm-morning';if(h>=7&&h<18)return 'farm-day';if(h>=18&&h<21)return 'countryside-evening';return 'night-insects';}
function shotFor(h,state,rand){const night=h<5||h>=21,pool=[];if(h>=5&&h<7.5)pool.push(['rooster',3]);if(!night&&!['rain','hail','snow'].includes(state.weather))pool.push(['songbird',2]);if(night)pool.push(['owl',1.5]);if(state.weather==='hail')pool.push(['thunder',3]);const kinds={chicken:'hen',cow:'cow',goat:'goat',horse:rand()<.5?'horse-whinny':'horse-snort'};const have=new Set((state.pens||[]).filter(p=>p.animals?.length).map(p=>p.species));for(const [species,slot] of Object.entries(kinds))if(have.has(species)&&!night)pool.push([slot,1.5]);const total=pool.reduce((n,[,w])=>n+w,0);let r=rand()*total;for(const [slot,w] of pool)if((r-=w)<=0)return slot;return null;}
async function loadCatalogue(){for(const url of SOURCES){try{const r=await fetch(url,{headers:{accept:'application/json'}});if(!r.ok)continue;const j=await r.json(),list=(Array.isArray(j)?j:j.sounds||[]).filter(s=>s.urls?.audio);if(!list.length)continue;const bySlot=new Map();for(const s of list){const k=s.slot||s.id;if(!bySlot.has(k))bySlot.set(k,[]);bySlot.get(k).push(s);}return bySlot;}catch{}}return null;}
export function createRanchSound(){let context=null,last=-Infinity,enabled=false,voices=0,master=null,catalogue=null,loading=null,bed=null,bedSlot=null;const buffers=new Map(),rand=Math.random;
function buffer(s){if(!buffers.has(s.id))buffers.set(s.id,fetch(s.urls.audio).then(r=>r.ok?r.arrayBuffer():Promise.reject(new Error(r.status))).then(b=>context.decodeAudioData(b)).catch(()=>null));return buffers.get(s.id);}
function pick(slot){const list=catalogue?.get(slot);return list?.length?list[Math.floor(rand()*list.length)]:null;}
async function setBed(slot){if(slot===bedSlot)return;bedSlot=slot;const s=pick(slot),old=bed;bed=null;const t=context.currentTime;if(old){old.gain.gain.setTargetAtTime(0,t,1.2);old.source.stop(t+5);}if(!s)return;const b=await buffer(s);if(!b||bedSlot!==slot||!enabled)return;const source=context.createBufferSource(),gain=context.createGain();source.buffer=b;source.loop=true;gain.gain.value=0;source.connect(gain).connect(master);source.start();gain.gain.setTargetAtTime(BED,context.currentTime,1.2);source.onended=()=>{source.disconnect();gain.disconnect();};bed={source,gain};}
async function oneShot(slot){const s=pick(slot);if(!s)return false;voices++;const b=await buffer(s);if(!b||!enabled){voices--;return false;}const source=context.createBufferSource(),gain=context.createGain(),pan=context.createStereoPanner?context.createStereoPanner():null;source.buffer=b;gain.gain.value=SHOT*(.6+.4*rand());let node=source.connect(gain);if(pan){pan.pan.value=rand()*1.6-.8;node=node.connect(pan);}node.connect(master);source.onended=()=>{source.disconnect();gain.disconnect();pan?.disconnect();voices--;};source.start();return true;}
function chirp(h){const oscillator=context.createOscillator(),gain=context.createGain();const t=context.currentTime;oscillator.type='sine';oscillator.frequency.setValueAtTime(h<8?1400:h>18?2400:380,t);oscillator.frequency.exponentialRampToValueAtTime(h<8?2200:h>18?1800:180,t+.12);gain.gain.setValueAtTime(.0001,t);gain.gain.exponentialRampToValueAtTime(.012,t+.02);gain.gain.exponentialRampToValueAtTime(.0001,t+.2);oscillator.connect(gain).connect(context.destination);voices++;oscillator.onended=()=>{oscillator.disconnect();gain.disconnect();voices--;};oscillator.start(t);oscillator.stop(t+.22);}
return {async enable(value){enabled=value;if(!value){if(context)await context.suspend();return;}context??=new (window.AudioContext||window.webkitAudioContext)();if(!master){master=context.createGain();master.gain.value=MASTER;master.connect(context.destination);}await context.resume();loading??=loadCatalogue().then(c=>{catalogue=c;});},
update(now,state){if(!enabled||!context||context.state!=='running')return;const h=state.calendar?.hour??12;if(catalogue){setBed(bedFor(h,state.weather));if(now-last<8||voices>=3)return;last=now;if(rand()<.55){const slot=shotFor(h,state,rand);if(slot)oneShot(slot);}return;}if(now-last<8||voices>=2)return;last=now;if(h<5||h>22)return;chirp(h);},
dispose(){enabled=false;bed?.source.stop();bed=null;context?.close();context=null;master=null;buffers.clear();}};}
export const ranchSoundRules={bedFor,shotFor};
